
import { NextRequest, NextResponse } from "next/server";
import { supabaseAdmin } from "@/lib/supabaseAdmin";

function authorized(req: NextRequest) {
  return Boolean(
    process.env.ADMIN_KEY &&
    req.headers.get("x-admin-key") === process.env.ADMIN_KEY
  );
}

export async function PUT(
  req: NextRequest,
  { params }: { params: Promise<{ id: string }> }
) {
  try {
    if (!authorized(req)) {
      return NextResponse.json(
        { error: "Unauthorized" },
        { status: 401 }
      );
    }

    const { id } = await params;
    const student = await req.json();

    if (
      !student.studentName?.trim() ||
      !student.email?.trim() ||
      student.consent !== true ||
      !Array.isArray(student.interests)
    ) {
      return NextResponse.json(
        { error: "Invalid student information or missing consent." },
        { status: 400 }
      );
    }

    const { data, error } = await supabaseAdmin
      .from("students")
      .update({
        student_name: student.studentName.trim(),
        email: student.email.trim(),
        phone: student.phone || null,
        city: student.city || null,
        stream: student.stream,
        interests: student.interests,
        experience: student.experience,
        favorite_subject: student.favoriteSubject || null,
        career_goal: student.careerGoal || null,
        language: student.language,
        guardian_consent: student.guardianConsent,
        consent: student.consent,
      })
      .eq("id", id)
      .select()
      .maybeSingle();

    if (error) throw error;

    if (!data) {
      return NextResponse.json(
        { error: "Student not found." },
        { status: 404 }
      );
    }

    return NextResponse.json({
      success: true,
      message: "Student updated successfully",
      student: data,
    });

  } catch (error) {
    console.error("Update student error:", error);

    return NextResponse.json(
      { error: "Unable to update student." },
      { status: 500 }
    );
  }
}

export async function DELETE(
  req: NextRequest,
  { params }: { params: Promise<{ id: string }> }
) {
  try {
    if (!authorized(req)) {
      return NextResponse.json(
        { error: "Unauthorized" },
        { status: 401 }
      );
    }

    const { id } = await params;

    const { data, error } = await supabaseAdmin
      .from("students")
      .delete()
      .eq("id", id)
      .select("id")
      .maybeSingle();

    if (error) throw error;

    if (!data) {
      return NextResponse.json(
        { error: "Student not found." },
        { status: 404 }
      );
    }

    return NextResponse.json({
      success: true,
      message: "Student deleted successfully",
    });

  } catch (error) {
    console.error("Delete student error:", error);

    return NextResponse.json(
      { error: "Unable to delete student." },
      { status: 500 }
    );
  }
}
